/* LISTENING — Conversations, Announcements, Academic Talks */
const N2 = { W: 'Woman', M: 'Man' };
CONTENT.conv = [
  { id: 'v01', diff: 1, ctx: 'Listen to a conversation between two students.', names: N2, lines: [['W', 'Hey, are you going to the study group tonight?'], ['M', 'I was planning to, but my shift at the café got extended. I won\'t be done until nine.'], ['W', 'That\'s too bad. We\'re reviewing chapter five, the one on market structures.'], ['M', 'Ugh, that\'s the one I need most. Could you send me your notes afterward?'], ['W', 'Sure, I\'ll take a photo and text them to you.']],
    qs: [{ q: 'Why can\'t the man attend the study group?', o: ['He has to work longer than planned', 'He is sick', 'He already studied chapter five', 'He forgot about it'], a: 0, x: '« my shift at the café got extended ».' }, { q: 'What will the woman do?', o: ['Explain the chapter to him tomorrow', 'Send him pictures of her notes', 'Cancel the study group', 'Ask the professor for help'], a: 1, x: '« I\'ll take a photo and text them to you ».' }] },
  { id: 'v02', diff: 2, ctx: 'Listen to a conversation between a student and a librarian.', names: { W: 'Librarian', M: 'Student' }, lines: [['M', 'Hi, I\'m looking for a book that\'s on reserve for my economics course, but the system says it\'s checked out.'], ['W', 'Reserve books can only be borrowed for two hours. Someone probably has it right now. It should be back by three.'], ['M', 'I have class at three. Is there another copy anywhere?'], ['W', 'Actually, we have an electronic version. You can read it online with your student login, though you can only download one chapter at a time.'], ['M', 'Perfect, one chapter is all I need.']],
    qs: [{ q: 'What is the student\'s problem?', o: ['He lost a library book', 'The book he needs is currently borrowed by someone else', 'He cannot log in to the system', 'He owes a late fee'], a: 1, x: 'Le livre est « checked out ».' }, { q: 'What can be inferred about the student\'s needs?', o: ['He needs the entire book', 'The electronic version will be sufficient for him', 'He will wait until three', 'He prefers printed books'], a: 1, x: '« one chapter is all I need ».' }] },
  { id: 'v03', diff: 2, ctx: 'Listen to a conversation between two students.', names: N2, lines: [['M', 'Did you see that the internship application now requires a video?'], ['W', 'Yeah, a two-minute introduction. Honestly, I\'m dreading it. I freeze up in front of a camera.'], ['M', 'Why don\'t you practice with me? I\'ll record you on my phone a few times until you feel more comfortable.'], ['W', 'That would actually help a lot. How about Thursday after lunch?'], ['M', 'Works for me.']],
    qs: [{ q: 'How does the woman feel about the video?', o: ['Excited', 'Anxious', 'Indifferent', 'Confident'], a: 1, x: '« I\'m dreading it. I freeze up ».' }, { q: 'What does the man offer to do?', o: ['Make the video for her', 'Help her rehearse by recording her', 'Write her introduction', 'Contact the company'], a: 1, x: 'Il propose de l\'enregistrer plusieurs fois pour s\'entraîner.' }] },
  { id: 'v04', diff: 3, ctx: 'Listen to a conversation between a student and a professor.', names: { W: 'Professor', M: 'Student' }, lines: [['M', 'Professor Hall, I wanted to ask about my paper topic. I\'d like to look at how microfinance affects women entrepreneurs.'], ['W', 'It\'s a rich topic, but as it stands, it\'s far too broad for ten pages. You\'d be skimming the surface.'], ['M', 'So I should narrow it down?'], ['W', 'Exactly. Pick one region, maybe even one lending program, and look at a specific outcome, like whether borrowers expanded their businesses. And make sure there\'s actually data available before you commit.'], ['M', 'That makes sense. I\'ll check the databases this weekend.']],
    qs: [{ q: 'What is the professor\'s main concern?', o: ['The topic is irrelevant to the course', 'The topic is too general for a short paper', 'The student lacks experience', 'Microfinance has been studied too much'], a: 1, x: '« far too broad for ten pages ».' }, { q: 'What does the professor advise the student to do before committing to a topic?', o: ['Interview entrepreneurs', 'Confirm that relevant data exist', 'Write the introduction', 'Choose a different subject'], a: 1, x: '« make sure there\'s actually data available ».' }] },
  { id: 'v05', diff: 1, ctx: 'Listen to a conversation at a campus café.', names: { W: 'Server', M: 'Student' }, lines: [['W', 'Hi, what can I get you?'], ['M', 'A large coffee and a blueberry muffin, please.'], ['W', 'Sorry, we just ran out of blueberry. We have banana or chocolate.'], ['M', 'Banana\'s fine. Can I pay by card?'], ['W', 'Of course.']],
    qs: [{ q: 'Why can\'t the man get what he first ordered?', o: ['The café is closing', 'There are no more blueberry muffins', 'He doesn\'t have enough money', 'The coffee machine is broken'], a: 1, x: '« we just ran out of blueberry ».' }, { q: 'What will the man most likely eat?', o: ['A chocolate muffin', 'A banana muffin', 'A blueberry muffin', 'Nothing'], a: 1, x: '« Banana\'s fine ».' }] },
  { id: 'v06', diff: 2, ctx: 'Listen to a conversation between two roommates.', names: N2, lines: [['W', 'The electricity bill came in, and it\'s almost double last month\'s.'], ['M', 'Seriously? It must be the heater in the living room. It\'s been on all day.'], ['W', 'Maybe we could set a timer so it only runs in the evening, when we\'re actually home.'], ['M', 'Good idea. And let\'s split this bill three ways as usual. I\'ll let Sam know.']],
    qs: [{ q: 'What does the man think caused the high bill?', o: ['A mistake by the company', 'The heater running all day', 'Their new roommate', 'Higher prices'], a: 1, x: '« It must be the heater... on all day ».' }, { q: 'What does the woman suggest?', o: ['Buying a new heater', 'Using a timer on the heater', 'Calling the company', 'Paying the bill alone'], a: 1, x: '« set a timer so it only runs in the evening ».' }] },
  { id: 'v07', diff: 3, ctx: 'Listen to a conversation between a student and an academic advisor.', names: { W: 'Advisor', M: 'Student' }, lines: [['M', 'I\'m thinking of taking five courses next semester so I can graduate early.'], ['W', 'That\'s ambitious. Which courses?'], ['M', 'Econometrics, corporate finance, two electives, and the thesis seminar.'], ['W', 'Econometrics and the thesis seminar together are notoriously demanding. Students who combine them often end up with lower grades in both. If your goal is a finance master\'s, your grades in those courses will matter more than graduating a semester early.'], ['M', 'Hmm, so maybe I should drop one of the electives instead.'], ['W', 'That would be a sensible compromise.']],
    qs: [{ q: 'Why is the advisor concerned?', o: ['The student has not paid tuition', 'The workload could hurt grades in important courses', 'The electives are not recognized', 'The thesis seminar is full'], a: 1, x: 'Econometrics + thesis seminar = très exigeant, risque pour les notes.' }, { q: 'What does the advisor imply about graduating early?', o: ['It is the most important goal', 'It is less important than strong grades for his plans', 'It is impossible', 'It is required for a master\'s'], a: 1, x: '« grades in those courses will matter more than graduating a semester early ».' }] },
  { id: 'v08', diff: 1, ctx: 'Listen to a conversation between two students.', names: N2, lines: [['M', 'Do you know if the pool is open today?'], ['W', 'I think it\'s closed for cleaning until Wednesday.'], ['M', 'Oh no. I wanted to swim before my exam.'], ['W', 'You could try the one downtown. It\'s only fifteen minutes by bike.']],
    qs: [{ q: 'Why is the pool closed?', o: ['It is being cleaned', 'It is a holiday', 'There is an exam', 'It is too cold'], a: 0, x: '« closed for cleaning ».' }, { q: 'What does the woman suggest?', o: ['Waiting until Wednesday', 'Going to another pool', 'Going running instead', 'Studying for the exam'], a: 1, x: 'La piscine du centre-ville.' }] },
  { id: 'v09', diff: 2, ctx: 'Listen to a conversation between a student and a housing office employee.', names: { W: 'Employee', M: 'Student' }, lines: [['M', 'Hi, I\'d like to request a room change. My room is right above the kitchen, and it\'s really noisy early in the morning.'], ['W', 'I understand. Room changes are processed after the first two weeks of the semester, so you\'d have to wait until next Monday to apply.'], ['M', 'Is there anything I can do before that?'], ['W', 'You can fill out the form now, and I\'ll put you at the top of the list once the period opens.']],
    qs: [{ q: 'Why does the student want to change rooms?', o: ['It is too small', 'It is too noisy', 'It is too expensive', 'It is far from campus'], a: 1, x: 'Bruit de la cuisine le matin.' }, { q: 'What will the employee do?', o: ['Change his room immediately', 'Give his request priority when changes begin', 'Refuse the request', 'Talk to the kitchen staff'], a: 1, x: '« put you at the top of the list ».' }] },
  { id: 'v10', diff: 3, ctx: 'Listen to a conversation between two classmates working on a project.', names: N2, lines: [['W', 'I\'ve been going through the survey responses, and something\'s off. Almost everyone rated the product five stars.'], ['M', 'Isn\'t that good news?'], ['W', 'Not if it\'s too good to be true. We only surveyed people who follow the brand on social media. They\'re already fans.'], ['M', 'Ah, so the sample\'s biased. Should we scrap the data?'], ['W', 'Not scrap it — but we need to acknowledge the limitation and, ideally, collect responses from a random group of shoppers too.']],
    qs: [{ q: 'What problem does the woman identify?', o: ['The survey had too few questions', 'The respondents were not representative', 'The product received poor ratings', 'Some data were lost'], a: 1, x: 'Échantillon biaisé : des fans de la marque.' }, { q: 'What does the woman propose?', o: ['Deleting all the data', 'Reporting the limitation and gathering more varied responses', 'Changing the product', 'Publishing the results immediately'], a: 1, x: '« acknowledge the limitation and... collect responses from a random group ».' }] },
  { id: 'v11', diff: 1, ctx: 'Listen to a conversation between two friends.', names: N2, lines: [['W', 'Are you coming to Emma\'s birthday dinner on Friday?'], ['M', 'I\'d love to, but my brother is visiting that weekend.'], ['W', 'Bring him along! Emma won\'t mind.'], ['M', 'Really? Okay, I\'ll ask him.']],
    qs: [{ q: 'Why did the man hesitate?', o: ['He doesn\'t like Emma', 'His brother is visiting', 'He has an exam', 'He is sick'], a: 1, x: '« my brother is visiting ».' }, { q: 'What does the woman suggest?', o: ['That he stay home', 'That he bring his brother', 'That he call Emma', 'That they change the date'], a: 1, x: '« Bring him along! »' }] },
  { id: 'v12', diff: 2, ctx: 'Listen to a conversation between a student and a professor.', names: { M: 'Professor', W: 'Student' }, lines: [['W', 'Professor, I missed the quiz on Tuesday because I had the flu. Is there any way I can make it up?'], ['M', 'Do you have a note from the health center?'], ['W', 'Yes, I have it here.'], ['M', 'Good. In that case, instead of a make-up quiz, I\'ll just count your final exam a bit more heavily. That\'s my standard policy.'], ['W', 'Oh, okay. Thank you.']],
    qs: [{ q: 'What does the student want?', o: ['An extension on an essay', 'A chance to make up a missed quiz', 'A higher grade', 'A note from the health center'], a: 1, x: '« Is there any way I can make it up? »' }, { q: 'How will the professor handle the situation?', o: ['Give her a make-up quiz', 'Give her zero', 'Increase the weight of the final exam', 'Let her retake the course'], a: 2, x: '« count your final exam a bit more heavily ».' }] },
  { id: 'v13', diff: 3, ctx: 'Listen to a conversation between two students.', names: N2, lines: [['M', 'So, did you decide between the consulting offer and the bank?'], ['W', 'Still torn. The consulting job pays more, but the travel is relentless — four days a week on the road.'], ['M', 'And the bank?'], ['W', 'Lower starting salary, but I\'d be on the M&A team, which is exactly what I want long-term. Plus, I could actually have a life.'], ['M', 'Sounds like you\'ve kind of already made up your mind.'], ['W', 'Maybe I have. I just needed to hear myself say it.']],
    qs: [{ q: 'What is the main drawback of the consulting job?', o: ['The low salary', 'The amount of travel', 'The location', 'The team'], a: 1, x: '« four days a week on the road ».' }, { q: 'What does the man imply?', o: ['The woman should choose consulting', 'The woman seems to prefer the bank', 'The woman should reject both offers', 'The woman needs more information'], a: 1, x: '« you\'ve kind of already made up your mind ».' }] },
  { id: 'v14', diff: 1, ctx: 'Listen to a conversation at a bookstore.', names: { W: 'Clerk', M: 'Student' }, lines: [['M', 'Excuse me, do you have the new edition of "Introduction to Statistics"?'], ['W', 'We\'re sold out, but more copies arrive on Thursday. I can reserve one for you.'], ['M', 'Yes, please. My name is Carlos.']],
    qs: [{ q: 'What is the problem?', o: ['The book is too expensive', 'The store has no copies right now', 'The book is the wrong edition', 'The store is closed'], a: 1, x: '« We\'re sold out ».' }, { q: 'What will the clerk do?', o: ['Order a different book', 'Keep a copy for Carlos', 'Call another store', 'Give him a discount'], a: 1, x: '« I can reserve one for you » → « Yes, please ».' }] },
  { id: 'v15', diff: 2, ctx: 'Listen to a conversation between two teammates.', names: N2, lines: [['W', 'Our presentation is twelve minutes, and the limit is ten.'], ['M', 'We could cut the history section. It\'s interesting, but it doesn\'t really support our main argument.'], ['W', 'Agreed. And I can speed up the data part if I skip the second chart.'], ['M', 'Let\'s rehearse again tomorrow and time it.']],
    qs: [{ q: 'What is the problem with the presentation?', o: ['It is too short', 'It is too long', 'It lacks data', 'It has no main argument'], a: 1, x: '12 minutes pour une limite de 10.' }, { q: 'Why does the man suggest removing the history section?', o: ['It is inaccurate', 'It is not essential to their argument', 'It is boring', 'It is too difficult'], a: 1, x: '« it doesn\'t really support our main argument ».' }] },
  { id: 'v16', diff: 3, ctx: 'Listen to a conversation between a student and a teaching assistant.', names: { M: 'TA', W: 'Student' }, lines: [['W', 'I don\'t understand why I lost points on question three. My final answer was correct.'], ['M', 'It was, but the question asked you to justify each step. You jumped from the equation straight to the result, so there was no way to tell whether you understood the method or just got lucky.'], ['W', 'So the reasoning matters as much as the answer.'], ['M', 'In this course, even more. On the final, a correct answer with no working will get at most half credit.']],
    qs: [{ q: 'Why did the student lose points?', o: ['Her answer was wrong', 'She did not show her reasoning', 'She answered the wrong question', 'She submitted late'], a: 1, x: 'Elle n\'a pas justifié chaque étape.' }, { q: 'What does the TA say about the final exam?', o: ['Only final answers will be graded', 'Answers without explanation will receive limited credit', 'It will not include question three', 'It will be easier'], a: 1, x: '« at most half credit ».' }] },
  { id: 'v17', diff: 1, ctx: 'Listen to a conversation between two students.', names: N2, lines: [['M', 'Which room is the chemistry exam in?'], ['W', 'It was moved to the main hall because so many people signed up.'], ['M', 'Thanks! I would have gone to the wrong place.']],
    qs: [{ q: 'Why was the exam moved?', o: ['The room was being repaired', 'Too many students registered', 'The professor asked for it', 'The main hall is quieter'], a: 1, x: '« so many people signed up ».' }, { q: 'How does the man feel?', o: ['Grateful for the information', 'Angry about the change', 'Worried about the exam', 'Confused about the date'], a: 0, x: '« Thanks! »' }] },
  { id: 'v18', diff: 2, ctx: 'Listen to a conversation between a student and a campus IT technician.', names: { W: 'Technician', M: 'Student' }, lines: [['M', 'My laptop keeps disconnecting from the campus Wi-Fi.'], ['W', 'Has this been happening since the update last week?'], ['M', 'Now that you mention it, yes.'], ['W', 'Then you probably need to reinstall the network certificate. It takes five minutes. Let me show you.']],
    qs: [{ q: 'What is the student\'s problem?', o: ['His laptop is broken', 'He loses his internet connection', 'He forgot his password', 'His battery dies quickly'], a: 1, x: 'Déconnexions du Wi-Fi.' }, { q: 'What is the likely cause?', o: ['A recent update', 'A virus', 'An old laptop', 'Too many users'], a: 0, x: 'Depuis la mise à jour → certificat à réinstaller.' }] },
  { id: 'v19', diff: 3, ctx: 'Listen to a conversation between two students.', names: N2, lines: [['W', 'Have you started reading for the ethics seminar? The article is sixty pages.'], ['M', 'I skimmed it. The gist is that companies shouldn\'t only maximize profits for shareholders, but I found the argument a bit one-sided.'], ['W', 'How so?'], ['M', 'The author barely addresses the obvious counterargument — that managers who pursue vague social goals become harder to hold accountable.'], ['W', 'That\'s a good point to raise in class, actually.']],
    qs: [{ q: 'What is the man\'s opinion of the article?', o: ['It is excellent and balanced', 'It neglects an important opposing argument', 'It is too short', 'It is only about shareholders'], a: 1, x: '« one-sided... barely addresses the obvious counterargument ».' }, { q: 'What does the woman suggest?', o: ['That he read it more carefully', 'That he share his criticism in class', 'That he change seminars', 'That he write to the author'], a: 1, x: '« That\'s a good point to raise in class ».' }] },
  { id: 'v20', diff: 1, ctx: 'Listen to a conversation between two students.', names: N2, lines: [['W', 'Do you want to share a taxi to the airport on Friday?'], ['M', 'Sure! What time is your flight?'], ['W', 'At two. We should leave around eleven.'], ['M', 'Perfect, mine is at two thirty.']],
    qs: [{ q: 'What does the woman propose?', o: ['Driving the man to the airport', 'Sharing a taxi', 'Taking the train', 'Changing flights'], a: 1, x: '« share a taxi ».' }, { q: 'When will they probably leave?', o: ['At two', 'Around eleven', 'At two thirty', 'In the evening'], a: 1, x: '« We should leave around eleven ».' }] },
  { id: 'v21', diff: 2, ctx: 'Listen to a conversation between a student and a career counselor.', names: { W: 'Counselor', M: 'Student' }, lines: [['M', 'I\'ve applied to fifteen internships and haven\'t heard back from any of them.'], ['W', 'Can I see the cover letter you\'ve been using?'], ['M', 'Sure, it\'s the same one for all of them.'], ['W', 'That might be the issue. Recruiters can tell when a letter is generic. Mention something specific about each company and why you\'d fit their team.']],
    qs: [{ q: 'What does the counselor think the problem is?', o: ['The student applied to too few companies', 'His cover letter is too generic', 'His grades are too low', 'He applied too late'], a: 1, x: 'La même lettre pour tous = générique.' }, { q: 'What does the counselor advise?', o: ['Tailoring each letter to the company', 'Applying to more companies', 'Calling recruiters directly', 'Removing the cover letter'], a: 0, x: 'Personnaliser chaque lettre.' }] },
  { id: 'v22', diff: 3, ctx: 'Listen to a conversation between two members of a student investment club.', names: N2, lines: [['M', 'I think we should put most of the club\'s fund into that renewable energy stock. It\'s up forty percent this year.'], ['W', 'That\'s exactly what worries me. We\'d be buying after the big run-up, and putting most of the fund in one company is a huge concentration risk.'], ['M', 'But the sector has strong tailwinds.'], ['W', 'Sure, so why not buy a sector fund instead? We\'d get the exposure without betting everything on a single firm.']],
    qs: [{ q: 'What is the woman\'s main concern?', o: ['Renewable energy has no future', 'The investment would be too concentrated', 'The club has no money', 'The stock price is too low'], a: 1, x: '« a huge concentration risk ».' }, { q: 'What does the woman propose?', o: ['Investing nothing', 'Buying a diversified fund in the same sector', 'Selling all stocks', 'Waiting a year'], a: 1, x: '« a sector fund... without betting everything on a single firm ».' }] },
  { id: 'v23', diff: 1, ctx: 'Listen to a conversation between two students.', names: N2, lines: [['M', 'Your presentation was great!'], ['W', 'Thanks! I was so nervous. Did I speak too fast?'], ['M', 'Maybe a little at the beginning, but after that it was perfect.']],
    qs: [{ q: 'How did the woman feel during her presentation?', o: ['Nervous', 'Bored', 'Angry', 'Tired'], a: 0, x: '« I was so nervous ».' }, { q: 'What does the man say about her speed?', o: ['She was too slow', 'She spoke a bit fast at the start', 'She was fast throughout', 'She was perfect from the start'], a: 1, x: '« a little at the beginning ».' }] },
  { id: 'v24', diff: 2, ctx: 'Listen to a conversation between a student and a professor.', names: { M: 'Professor', W: 'Student' }, lines: [['W', 'I\'m interested in your research on consumer behavior. Are you taking research assistants this summer?'], ['M', 'I might have one position. Have you taken the research methods course?'], ['W', 'I\'m taking it now.'], ['M', 'Good. Send me your CV and a short paragraph on why you\'re interested. I\'ll decide by the end of the month.']],
    qs: [{ q: 'Why does the student visit the professor?', o: ['To ask about a grade', 'To ask about a research assistant position', 'To discuss a paper', 'To register for a course'], a: 1, x: 'Poste d\'assistant de recherche.' }, { q: 'What does the professor ask the student to send?', o: ['A transcript', 'A CV and a brief statement of interest', 'A research proposal', 'Two recommendation letters'], a: 1, x: '« your CV and a short paragraph ».' }] },
  { id: 'v25', diff: 3, ctx: 'Listen to a conversation between two students.', names: N2, lines: [['W', 'I read that the university is replacing some lectures with recorded videos to cut costs.'], ['M', 'Honestly, for big intro courses, I don\'t see the harm. I barely ask questions in a room of four hundred people anyway.'], ['W', 'Maybe, but at least the lecture forces you to show up. With videos, I know I\'d fall behind.'], ['M', 'Fair. I guess it depends on how disciplined you are.']],
    qs: [{ q: 'What is the man\'s view of recorded lectures for large courses?', o: ['They are harmful', 'They are acceptable', 'They are better than seminars', 'They should be banned'], a: 1, x: '« I don\'t see the harm ».' }, { q: 'Why is the woman skeptical?', o: ['Videos are low quality', 'She would be less likely to keep up without attending', 'She likes asking questions', 'Videos are expensive'], a: 1, x: '« With videos, I know I\'d fall behind ».' }] },
  { id: 'v26', diff: 2, ctx: 'Listen to a conversation at the student health center.', names: { W: 'Receptionist', M: 'Student' }, lines: [['M', 'Hi, I\'d like to see a doctor today. I\'ve had a sore throat for three days.'], ['W', 'We don\'t have any appointments left today, but there\'s a walk-in clinic from four to six. You might have to wait a bit.'], ['M', 'That\'s fine. I\'ll come back at four.']],
    qs: [{ q: 'Why can\'t the student get an appointment?', o: ['The clinic is closed', 'All appointments are taken', 'He needs insurance', 'The doctor is sick'], a: 1, x: '« We don\'t have any appointments left today ».' }, { q: 'What will the student do?', o: ['Go to a hospital', 'Come back during walk-in hours', 'Book for tomorrow', 'Call later'], a: 1, x: '« I\'ll come back at four ».' }] },
  { id: 'v27', diff: 3, ctx: 'Listen to a conversation between a student and a professor after class.', names: { W: 'Professor', M: 'Student' }, lines: [['M', 'In today\'s lecture, you said minimum wage increases don\'t necessarily reduce employment. But isn\'t that what the supply and demand model predicts?'], ['W', 'In a perfectly competitive labor market, yes. But when a few employers dominate a local market, they can pay below what workers produce. In that case, a moderate minimum wage can actually increase employment.'], ['M', 'So the basic model is just a special case.'], ['W', 'Exactly. That\'s the key takeaway for next week\'s problem set.']],
    qs: [{ q: 'What confused the student?', o: ['The date of the problem set', 'A claim that seemed to contradict a basic model', 'The professor\'s grading', 'The definition of employment'], a: 1, x: 'Contradiction apparente avec l\'offre et la demande.' }, { q: 'According to the professor, when might a minimum wage increase employment?', o: ['When markets are perfectly competitive', 'When a few employers dominate the local labor market', 'When unemployment is zero', 'When wages are already high'], a: 1, x: 'Situation de monopsone : peu d\'employeurs.' }] },
  { id: 'v28', diff: 1, ctx: 'Listen to a conversation between two neighbors in a residence hall.', names: N2, lines: [['W', 'Hi, sorry to bother you. Could you turn your music down a little? I have an exam tomorrow.'], ['M', 'Oh, of course. Sorry about that! Good luck tomorrow.']],
    qs: [{ q: 'What does the woman ask?', o: ['To borrow some music', 'To lower the volume', 'To study together', 'To turn off the lights'], a: 1, x: '« turn your music down ».' }, { q: 'How does the man respond?', o: ['He refuses', 'He agrees and apologizes', 'He gets angry', 'He ignores her'], a: 1, x: '« Of course. Sorry about that! »' }] },
  { id: 'v29', diff: 2, ctx: 'Listen to a conversation between two students.', names: N2, lines: [['M', 'I\'m thinking of studying abroad next year, but I\'m worried about the cost.'], ['W', 'Have you looked at the exchange programs? You pay your normal tuition here, not the foreign university\'s.'], ['M', 'Really? That changes everything. Where do I find the list?'], ['W', 'The international office website. The deadline is in November, though.']],
    qs: [{ q: 'What is the man worried about?', o: ['The language', 'The cost', 'His grades', 'Being far from family'], a: 1, x: '« worried about the cost ».' }, { q: 'Why does the man say "That changes everything"?', o: ['Exchange programs would be more affordable than he thought', 'The deadline has passed', 'He no longer wants to go abroad', 'He found a scholarship'], a: 0, x: 'Il paierait les frais de son université, pas ceux de l\'étranger.' }] },
  { id: 'v30', diff: 3, ctx: 'Listen to a conversation between two students preparing for a debate.', names: N2, lines: [['W', 'We\'re arguing that cities should ban cars from their centers. What\'s our strongest point?'], ['M', 'Air quality. The health data are hard to dispute.'], ['W', 'Agreed. But the other team will say it hurts small shops.'], ['M', 'Then we pre-empt it. Several cities saw retail sales rise after pedestrianization because people linger longer when streets are pleasant.'], ['W', 'Nice. Let\'s make sure we cite specific examples, not just claim it.']],
    qs: [{ q: 'What does the man mean by "we pre-empt it"?', o: ['They will ignore the argument', 'They will address the objection before the other team raises it', 'They will change their position', 'They will ask for more time'], a: 1, x: 'Anticiper l\'objection.' }, { q: 'What does the woman insist on?', o: ['Using specific evidence', 'Speaking more loudly', 'Avoiding health arguments', 'Changing the topic'], a: 0, x: '« cite specific examples, not just claim it ».' }] },
];

CONTENT.ann = [
  { id: 'n01', diff: 1, g: 'W', ctx: 'Listen to an announcement at the beginning of a class.', text: 'Good morning, everyone. Before we start, a quick reminder: your group projects are due next Friday, not this Friday as it says in the syllabus. That was a typo. Also, I\'ve posted the grading rubric online, so please check it before you finalize your work.',
    qs: [{ q: 'What is the main purpose of the announcement?', o: ['To correct a date and share information about grading', 'To cancel the project', 'To introduce a new topic', 'To form groups'], a: 0, x: 'Correction de la date + rubric en ligne.' }, { q: 'Why was the date in the syllabus wrong?', o: ['The professor changed her mind', 'It was a typing mistake', 'Students asked for more time', 'The university changed the calendar'], a: 1, x: '« That was a typo ».' }, { q: 'What does the professor ask students to do?', o: ['Submit early', 'Review the grading rubric', 'Email her', 'Change groups'], a: 1, x: '« please check it before you finalize your work ».' }] },
  { id: 'n02', diff: 2, g: 'M', ctx: 'Listen to an announcement on the campus radio.', text: 'Attention, students. Due to the snowstorm expected tonight, all classes scheduled before noon tomorrow are cancelled. Afternoon classes will run as normal unless you receive an email saying otherwise. The dining halls will remain open, but the shuttle service will be suspended until the roads are cleared. Please avoid unnecessary travel.',
    qs: [{ q: 'Which classes are cancelled?', o: ['All classes tomorrow', 'Morning classes tomorrow', 'Afternoon classes tomorrow', 'Evening classes tonight'], a: 1, x: '« all classes scheduled before noon ».' }, { q: 'What service will stop temporarily?', o: ['The dining halls', 'The shuttle', 'Email', 'The library'], a: 1, x: 'La navette est suspendue.' }, { q: 'How will students know if afternoon classes are cancelled?', o: ['On the radio', 'By email', 'From their roommates', 'On a sign'], a: 1, x: '« unless you receive an email saying otherwise ».' }] },
  { id: 'n03', diff: 2, g: 'W', ctx: 'Listen to an announcement in a university library.', text: 'May I have your attention, please. The library will be closing in fifteen minutes. Please bring any items you wish to borrow to the front desk now, as the self-checkout machines have already been shut down for the night. Group study rooms must be vacated immediately. Thank you, and have a good evening.',
    qs: [{ q: 'What is the announcement mainly about?', o: ['The library\'s new hours', 'The library closing soon', 'A lost item', 'A new study room'], a: 1, x: 'Fermeture dans 15 minutes.' }, { q: 'Why must students go to the front desk to borrow books?', o: ['The self-checkout machines are turned off', 'The desk offers longer loans', 'Books are free there', 'The machines are broken permanently'], a: 0, x: 'Automates déjà éteints.' }, { q: 'What must students in group study rooms do?', o: ['Wait fifteen minutes', 'Leave right away', 'Return their keys tomorrow', 'Lower their voices'], a: 1, x: '« must be vacated immediately ».' }] },
  { id: 'n04', diff: 3, g: 'M', ctx: 'Listen to an announcement made by a professor at the start of a lecture.', text: 'Before we begin, I want to address the midterm results. The class average was considerably lower than in previous years, and after reviewing the exam, I believe question four was ambiguously worded. So I\'ve decided to accept two interpretations of that question and regrade it accordingly. You\'ll see updated scores online by Thursday. If your grade doesn\'t change, it means your original answer was already credited.',
    qs: [{ q: 'Why is the professor regrading part of the exam?', o: ['Students complained about the time limit', 'One question could be understood in more than one way', 'The average was too high', 'Some exams were lost'], a: 1, x: '« ambiguously worded ».' }, { q: 'What does it mean if a student\'s grade stays the same?', o: ['The regrading has not happened yet', 'The student\'s answer had already received credit', 'The student failed question four', 'The student must contact the professor'], a: 1, x: '« your original answer was already credited ».' }, { q: 'When will updated scores be available?', o: ['Today', 'By Thursday', 'Next week', 'At the final exam'], a: 1, x: '« by Thursday ».' }] },
  { id: 'n05', diff: 1, g: 'W', ctx: 'Listen to an announcement at a campus sports center.', text: 'Hello, everyone. The swimming pool will be closed this weekend for repairs. It will open again on Monday at seven a.m. During the weekend, the gym and tennis courts will stay open as usual. We\'re sorry for any inconvenience.',
    qs: [{ q: 'Why will the pool be closed?', o: ['For a competition', 'For repairs', 'For cleaning', 'For a holiday'], a: 1, x: '« for repairs ».' }, { q: 'When will the pool open again?', o: ['Saturday', 'Sunday', 'Monday morning', 'Monday evening'], a: 2, x: '« Monday at seven a.m. ».' }, { q: 'What will remain open this weekend?', o: ['Only the pool', 'The gym and tennis courts', 'Nothing', 'Only the café'], a: 1, x: 'Gym et tennis ouverts.' }] },
  { id: 'n06', diff: 2, g: 'M', ctx: 'Listen to an announcement from the career center.', text: 'Hi, everyone. This is a reminder that the spring career fair is next Wednesday in the student union. More than sixty employers will attend, including several major banks and consulting firms. To make the most of it, we strongly recommend attending one of our CV review workshops this week. Spaces are limited, so sign up on the career portal as soon as possible. And don\'t forget to dress professionally on the day.',
    qs: [{ q: 'What is the main purpose of the announcement?', o: ['To promote the career fair and related preparation', 'To announce job offers', 'To cancel the fair', 'To recruit volunteers'], a: 0, x: 'Rappel du forum + ateliers CV.' }, { q: 'What does the speaker recommend doing this week?', o: ['Applying to banks', 'Attending a CV workshop', 'Buying a suit', 'Visiting employers'], a: 1, x: '« attending one of our CV review workshops ».' }, { q: 'Why should students register quickly?', o: ['The fair is tomorrow', 'Workshop places are limited', 'Registration costs more later', 'Employers need the list'], a: 1, x: '« Spaces are limited ».' }] },
  { id: 'n07', diff: 3, g: 'W', ctx: 'Listen to an announcement by a department administrator.', text: 'Good afternoon. As some of you know, the department is moving to a new building over the summer. During the transition, faculty offices will be relocated in stages, so office hours may temporarily take place in the seminar rooms on the ground floor. Please check each instructor\'s page for their current location before showing up. We also ask thesis students to collect any personal belongings from the graduate lounge by June first, after which remaining items will be donated.',
    qs: [{ q: 'Why might office hours be held in seminar rooms?', o: ['Offices are being moved gradually', 'Too many students attend', 'The old building is closed', 'Instructors prefer larger rooms'], a: 0, x: 'Déménagement « in stages ».' }, { q: 'What should students do before going to office hours?', o: ['Email the administrator', 'Check the instructor\'s page for the location', 'Book a seminar room', 'Go to the graduate lounge'], a: 1, x: '« check each instructor\'s page ».' }, { q: 'What will happen to items left in the graduate lounge after June first?', o: ['They will be moved to the new building', 'They will be given away', 'They will be stored', 'They will be returned to students'], a: 1, x: '« will be donated ».' }] },
  { id: 'n08', diff: 1, g: 'M', ctx: 'Listen to an announcement in a campus cafeteria.', text: 'Good afternoon, everyone. Today is International Food Day in the cafeteria! We are serving dishes from Mexico, India, and Japan. Students who try all three dishes can get a free dessert. Just show your receipt at the counter.',
    qs: [{ q: 'What is special about today?', o: ['The cafeteria is closed', 'Food from different countries is served', 'All food is free', 'A new chef is starting'], a: 1, x: 'Plats du Mexique, d\'Inde, du Japon.' }, { q: 'How can students get a free dessert?', o: ['By arriving early', 'By trying all three dishes', 'By paying by card', 'By bringing a friend'], a: 1, x: '« try all three dishes ».' }, { q: 'What must students show?', o: ['Their ID', 'Their receipt', 'Their ticket', 'Their menu'], a: 1, x: '« show your receipt ».' }] },
  { id: 'n09', diff: 2, g: 'W', ctx: 'Listen to an announcement at the start of a lab session.', text: 'Okay, before we get started with today\'s experiment, two quick safety points. First, the fume hood at station three isn\'t working properly, so no one should use that station today. Second, remember that goggles stay on for the entire session, even when you\'re just writing up your results. Anyone without goggles will be asked to leave. Now, please take out your lab manuals.',
    qs: [{ q: 'Why should students avoid station three?', o: ['It is reserved', 'Its equipment is not functioning correctly', 'It is too crowded', 'It is being cleaned'], a: 1, x: 'La hotte ne fonctionne pas bien.' }, { q: 'When must students wear goggles?', o: ['Only during the experiment', 'During the whole session', 'Only at station three', 'Only when writing'], a: 1, x: '« for the entire session ».' }, { q: 'What will the instructor probably do next?', o: ['End the class', 'Begin explaining the experiment', 'Repair the fume hood', 'Check homework'], a: 1, x: '« please take out your lab manuals ».' }] },
  { id: 'n10', diff: 3, g: 'M', ctx: 'Listen to an announcement from the dean of students.', text: 'Good evening. I\'m writing — or rather, speaking — to let you know about an important change to the course evaluation process. Starting this term, evaluations will be completed during class time in the final week, rather than online afterward. Participation rates had fallen below thirty percent, which made the results difficult to interpret. Responses remain completely anonymous, and instructors will not see them until after final grades are submitted.',
    qs: [{ q: 'What change is being announced?', o: ['Course evaluations will be done in class', 'Evaluations will be cancelled', 'Grades will be posted online', 'Instructors will evaluate students differently'], a: 0, x: 'Évaluations en classe pendant la dernière semaine.' }, { q: 'Why was the change made?', o: ['Students complained about anonymity', 'Too few students completed evaluations online', 'Instructors requested it', 'The online system was hacked'], a: 1, x: 'Participation < 30 %.' }, { q: 'Why does the speaker mention that instructors see responses only after grades are submitted?', o: ['To reassure students that honest feedback will not affect their grades', 'To explain a delay', 'To criticize instructors', 'To encourage negative comments'], a: 0, x: 'Rassurer : pas d\'impact sur les notes.' }] },
  { id: 'n11', diff: 2, g: 'W', ctx: 'Listen to an announcement at the start of an orientation session.', text: 'Welcome to orientation, everyone! Today\'s schedule has changed slightly. The campus tour, which was planned for this morning, will now take place after lunch because of the rain. So we\'ll begin with the presentation on academic resources here in the auditorium. Lunch will be served at twelve thirty in the main dining hall, and your meal tickets are in the welcome packs.',
    qs: [{ q: 'Why was the campus tour rescheduled?', o: ['Because of the weather', 'Because the guide is late', 'Because lunch was moved', 'Because of a meeting'], a: 0, x: '« because of the rain ».' }, { q: 'What will happen first?', o: ['Lunch', 'The campus tour', 'A presentation about academic resources', 'Registration'], a: 2, x: '« we\'ll begin with the presentation ».' }, { q: 'Where can students find their meal tickets?', o: ['At the dining hall', 'In their welcome packs', 'At the auditorium entrance', 'Online'], a: 1, x: '« in the welcome packs ».' }] },
  { id: 'n12', diff: 3, g: 'M', ctx: 'Listen to a professor\'s announcement about an assignment.', text: 'A few of you have asked whether you can use AI tools for the case study. Here\'s my position: you may use them to brainstorm or to check your grammar, but the analysis itself must be your own. If you use such a tool, include a short note at the end explaining how you used it. Undisclosed use will be treated as a breach of academic integrity, not because the tools are forbidden, but because transparency is.',
    qs: [{ q: 'What is the professor\'s policy on AI tools?', o: ['They are completely forbidden', 'They are allowed for limited purposes if their use is disclosed', 'They can be used to write the analysis', 'They are required'], a: 1, x: 'Autorisés pour brainstormer/grammaire, avec mention.' }, { q: 'What must students do if they use an AI tool?', o: ['Ask permission first', 'Add a note explaining how they used it', 'Submit two versions', 'Use it only for grammar'], a: 1, x: '« include a short note at the end ».' }, { q: 'What does the professor mean by the last sentence?', o: ['Using AI tools is always cheating', 'The real issue is hiding the use of the tools', 'Transparency is forbidden', 'Grammar checkers are forbidden'], a: 1, x: 'Le problème, c\'est la dissimulation.' }] },
  { id: 'n13', diff: 1, g: 'W', ctx: 'Listen to an announcement on a campus bus.', text: 'Attention, passengers. Because of road work on Main Street, this bus will not stop at the library today. Passengers going to the library should get off at the next stop, the Student Center, and walk for about five minutes. Thank you for your patience.',
    qs: [{ q: 'Why will the bus skip a stop?', o: ['The driver is late', 'There is road work', 'The library is closed', 'The bus is full'], a: 1, x: '« road work on Main Street ».' }, { q: 'What should people going to the library do?', o: ['Stay on the bus', 'Get off at the Student Center and walk', 'Take a taxi', 'Wait for another bus'], a: 1, x: 'Descendre au Student Center et marcher.' }, { q: 'How long is the walk?', o: ['About two minutes', 'About five minutes', 'About fifteen minutes', 'About an hour'], a: 1, x: '« about five minutes ».' }] },
  { id: 'n14', diff: 2, g: 'M', ctx: 'Listen to an announcement at the start of a seminar.', text: 'Before we dive in, a quick change to the reading list. The article by Martinez has been replaced with a more recent study, because the original data were revised last month and some of the conclusions no longer hold. The new article is already on the course website. Please read it before Thursday, since we\'ll be discussing it in detail. The rest of the list stays the same.',
    qs: [{ q: 'Why was one article replaced?', o: ['It was too long', 'Its data were revised and some conclusions became invalid', 'Students did not like it', 'The author asked for it'], a: 1, x: '« the original data were revised... conclusions no longer hold ».' }, { q: 'Where can students find the new article?', o: ['In the library', 'On the course website', 'In their email', 'At the bookstore'], a: 1, x: '« already on the course website ».' }, { q: 'When should students read the new article?', o: ['Before Thursday', 'Next week', 'Today', 'Before the final exam'], a: 0, x: '« before Thursday ».' }] },
];

CONTENT.talk = [
  { id: 't01', diff: 2, g: 'W', ctx: 'Listen to part of a lecture in a biology class.', text: 'Today, let\'s talk about camouflage. Many animals avoid predators by blending into their surroundings, but camouflage isn\'t just about color. Take the cuttlefish, for example. It can change not only its color but also the texture of its skin in less than a second, matching rocks, sand, or seaweed. What\'s remarkable is that cuttlefish are thought to be color-blind. So how do they match colors they can\'t see? One hypothesis is that light-sensitive proteins in their skin detect light directly. Another is that they rely on brightness and contrast rather than color itself. Researchers are still debating this, and it\'s a nice reminder that even well-studied behaviors can hold surprises.',
    qs: [{ q: 'What is the talk mainly about?', o: ['How cuttlefish hunt', 'The cuttlefish\'s camouflage abilities and an unresolved question about them', 'Why most animals are color-blind', 'The texture of seaweed'], a: 1, x: 'Camouflage + énigme de la cécité aux couleurs.' }, { q: 'According to the professor, what makes the cuttlefish\'s ability surprising?', o: ['It changes color very slowly', 'It seems unable to see color', 'It lives only in sand', 'It has no predators'], a: 1, x: '« cuttlefish are thought to be color-blind ».' }, { q: 'What is one hypothesis mentioned?', o: ['Cuttlefish copy other animals', 'Their skin may detect light directly', 'They memorize their environment', 'They use sound'], a: 1, x: '« light-sensitive proteins in their skin ».' }, { q: 'Why does the professor say it is "a nice reminder"?', o: ['To show that science is complete', 'To emphasize that familiar topics can still be mysterious', 'To criticize researchers', 'To end the course'], a: 1, x: 'Même des comportements bien étudiés réservent des surprises.' }] },
  { id: 't02', diff: 3, g: 'M', ctx: 'Listen to part of a lecture in an economics class.', text: 'Let\'s turn to the concept of moral hazard. Moral hazard arises when one party is protected from the consequences of its own risky behavior, so it has less incentive to be careful. Insurance is the classic case: someone with full car insurance might drive a bit less cautiously. But the concept became front-page news after the 2008 financial crisis. When governments rescued large banks, critics argued this created moral hazard on a massive scale. If banks believe they\'re "too big to fail," they may take on excessive risk, knowing that taxpayers will absorb the losses. Now, regulators responded by requiring banks to hold more capital, essentially forcing shareholders to have more skin in the game. Whether that\'s been enough is still hotly debated.',
    qs: [{ q: 'What is the main topic of the talk?', o: ['The history of car insurance', 'Moral hazard and its role in banking', 'How to prevent car accidents', 'Taxpayer rights'], a: 1, x: 'Définition du risque moral puis application aux banques.' }, { q: 'Why does the professor mention car insurance?', o: ['To give a simple example of moral hazard', 'To compare insurers and banks\' profits', 'To recommend full coverage', 'To criticize drivers'], a: 0, x: 'Exemple classique.' }, { q: 'What does "too big to fail" imply in this context?', o: ['Banks are too large to manage', 'Banks expect to be rescued if they get into trouble', 'Banks cannot make losses', 'Banks are protected by shareholders'], a: 1, x: 'Elles s\'attendent à être sauvées.' }, { q: 'What is the purpose of higher capital requirements, according to the professor?', o: ['To increase bank profits', 'To make shareholders bear more of the risk', 'To lower interest rates', 'To reduce taxes'], a: 1, x: '« skin in the game » = les actionnaires assument davantage le risque.' }] },
  { id: 't03', diff: 1, g: 'W', ctx: 'Listen to part of a talk in an environmental science class.', text: 'Good morning. Today we\'re looking at urban heat islands. Cities are often several degrees warmer than the countryside around them. Why? First, materials like concrete and asphalt absorb heat during the day and release it at night. Second, there are fewer trees and plants, which normally cool the air. And third, cars and air conditioners produce extra heat. The good news is that cities can do something about it. Planting trees, creating green roofs, and using light-colored materials on roads and buildings can all lower temperatures.',
    qs: [{ q: 'What is an urban heat island?', o: ['A park in the city', 'A city that is warmer than its surroundings', 'An island near a city', 'A building with air conditioning'], a: 1, x: 'Ville plus chaude que la campagne autour.' }, { q: 'Which cause is NOT mentioned?', o: ['Concrete and asphalt', 'Fewer plants', 'Heat from cars', 'Higher humidity'], a: 3, x: 'L\'humidité n\'est pas mentionnée.' }, { q: 'Why do trees help?', o: ['They cool the air', 'They block traffic', 'They absorb noise', 'They produce heat at night'], a: 0, x: '« which normally cool the air ».' }, { q: 'What is the professor\'s attitude at the end?', o: ['Pessimistic', 'Hopeful that solutions exist', 'Uninterested', 'Angry'], a: 1, x: '« The good news is… ».' }] },
  { id: 't04', diff: 2, g: 'M', ctx: 'Listen to part of a lecture in a psychology class.', text: 'So, the bystander effect. In the 1960s, psychologists John Darley and Bibb Latané ran experiments showing that people are less likely to help someone in need when other people are present. In one study, participants heard what sounded like another student having a seizure. When they believed they were alone, most of them went for help quickly. But when they believed four other people could also hear, many never went for help at all. Darley and Latané explained this through diffusion of responsibility: when many people are present, each person feels less personally responsible. Interestingly, more recent research using real-life camera footage suggests that in actual public conflicts, someone intervenes in the vast majority of cases. So the effect may be weaker in real life than the lab suggested.',
    qs: [{ q: 'What did the early experiments show?', o: ['People help more when others are present', 'People help less when others are present', 'Groups always ignore emergencies', 'Students rarely have seizures'], a: 1, x: 'Moins d\'aide en présence d\'autres personnes.' }, { q: 'What is "diffusion of responsibility"?', o: ['The feeling that responsibility is shared among many people', 'A medical condition', 'A legal rule', 'A type of training'], a: 0, x: 'Chacun se sent moins responsable.' }, { q: 'Why does the professor mention camera footage?', o: ['To confirm the lab results exactly', 'To present evidence that the effect may be weaker in real life', 'To show how experiments are recorded', 'To criticize the use of cameras'], a: 1, x: 'Dans la vraie vie, quelqu\'un intervient dans la grande majorité des cas.' }, { q: 'What can be inferred about the professor\'s view?', o: ['The bystander effect is completely false', 'Laboratory findings should be checked against real-world data', 'Darley and Latané were dishonest', 'People never help strangers'], a: 1, x: 'Nuance entre laboratoire et réalité.' }] },
  { id: 't05', diff: 3, g: 'W', ctx: 'Listen to part of a lecture in an art history class.', text: 'I want to spend a few minutes on the Dutch Golden Age, roughly the seventeenth century. What\'s unusual about this period is the art market itself. In most of Europe, painters depended on patrons, the church, the aristocracy, who commissioned specific works. In the Dutch Republic, by contrast, a prosperous merchant class bought paintings on the open market, often ready-made, from dealers or even at fairs. This had a profound effect on subject matter. Instead of grand religious scenes, you see still lifes, landscapes, and everyday domestic interiors, subjects that appealed to middle-class buyers decorating their homes. Painters also began to specialize. One artist might paint only seascapes, another only flowers, which allowed them to work efficiently and build a recognizable brand, so to speak. In a sense, it was one of the first genuinely commercial art markets.',
    qs: [{ q: 'What is the main point of the lecture?', o: ['Dutch painters were mostly religious', 'The structure of the Dutch art market shaped the art that was produced', 'Seascapes were the most expensive paintings', 'The aristocracy controlled Dutch art'], a: 1, x: 'Le marché a influencé les sujets.' }, { q: 'How did the Dutch art market differ from the rest of Europe?', o: ['Paintings were sold on an open market to merchants', 'The church bought most paintings', 'Painting was forbidden', 'Artists were paid by the state'], a: 0, x: 'Marché ouvert, marchands, foires.' }, { q: 'Why did painters specialize?', o: ['It was required by law', 'It helped them work efficiently and be recognized', 'Their patrons demanded it', 'Materials were limited'], a: 1, x: 'Efficacité + « recognizable brand ».' }, { q: 'Why does the professor say "so to speak"?', o: ['To show that she is using a modern business term loosely', 'To correct a mistake', 'To quote a painter', 'To introduce a question'], a: 0, x: 'Elle applique un terme moderne (« brand ») de façon approximative.' }] },
  { id: 't06', diff: 2, g: 'M', ctx: 'Listen to part of a talk in a geology class.', text: 'Let\'s consider how scientists date rocks. One of the most important methods is radiometric dating. Certain elements are unstable, which means they gradually transform into other elements at a constant rate. For example, uranium slowly decays into lead. The time it takes for half of the uranium in a sample to change is called its half-life, and for one form of uranium, that\'s about four and a half billion years. So, by measuring the ratio of uranium to lead in a mineral, geologists can calculate how long ago it formed. Using this technique, scientists have estimated that the Earth itself is about four point five billion years old.',
    qs: [{ q: 'What is the talk mainly about?', o: ['How uranium is mined', 'A method for determining the age of rocks', 'The formation of lead', 'Dangerous elements'], a: 1, x: 'La datation radiométrique.' }, { q: 'What is a half-life?', o: ['The time for half of an unstable element in a sample to transform', 'Half the age of the Earth', 'The time a rock takes to form', 'The life of a geologist'], a: 0, x: 'Définition donnée.' }, { q: 'What do geologists measure to date a mineral?', o: ['Its weight', 'The ratio between uranium and lead', 'Its color', 'Its temperature'], a: 1, x: '« the ratio of uranium to lead ».' }, { q: 'What conclusion has this method allowed?', o: ['The Earth is about 4.5 billion years old', 'Uranium is disappearing', 'All rocks are the same age', 'Lead is unstable'], a: 0, x: 'Âge de la Terre.' }] },
  { id: 't07', diff: 3, g: 'W', ctx: 'Listen to part of a lecture in a business class.', text: 'Today\'s topic is disruptive innovation, a term coined by Clayton Christensen. Now, people often use "disruptive" to mean any exciting new technology, but that\'s not what Christensen meant. In his theory, disruption typically starts at the bottom of a market. A newcomer offers a product that\'s cheaper and simpler, and frankly worse by traditional standards, so established firms ignore it. Their best customers don\'t want it, and the margins are low. But the newcomer improves steadily, and eventually it becomes good enough for mainstream customers, at which point the incumbents are in trouble. The paradox is that the established companies weren\'t badly managed. They did exactly what good management recommends, listening to their most profitable customers. That rational behavior is precisely what left them vulnerable.',
    qs: [{ q: 'What misconception does the professor address?', o: ['That innovation is always expensive', 'That "disruptive" simply means any exciting new technology', 'That newcomers never succeed', 'That Christensen studied only technology firms'], a: 1, x: 'Ce n\'est pas n\'importe quelle nouveauté.' }, { q: 'According to the theory, where does disruption usually begin?', o: ['At the high end of the market', 'At the low end of the market, with simpler products', 'In government research', 'Among the best customers'], a: 1, x: '« starts at the bottom of a market ».' }, { q: 'Why do established firms initially ignore the newcomer?', o: ['Its product appeals little to their best customers and offers low margins', 'It is illegal', 'It is too expensive', 'They have not heard of it'], a: 0, x: 'Clients rentables pas intéressés, marges faibles.' }, { q: 'What is the paradox the professor describes?', o: ['Poorly managed firms survive', 'Good management practices can make firms vulnerable', 'Cheap products are always better', 'Customers do not know what they want'], a: 1, x: 'Le comportement rationnel les a rendues vulnérables.' }] },
  { id: 't08', diff: 1, g: 'M', ctx: 'Listen to part of a talk in a history class.', text: 'Today we\'ll talk about the Great Wall of China. Many people think it is one single wall, but in fact it is a series of walls built by different dynasties over more than two thousand years. The most famous parts, the ones tourists visit today, were built during the Ming dynasty, about five hundred years ago. The walls were built to protect China from invasions from the north. They also helped control trade and travel. Another popular belief is that you can see the wall from space with your eyes. Astronauts say this is not true: the wall is very long, but it is too narrow.',
    qs: [{ q: 'What is the first misconception the speaker corrects?', o: ['That the wall is in China', 'That the wall is a single structure', 'That the wall is old', 'That tourists visit it'], a: 1, x: 'Une série de murs, pas un seul.' }, { q: 'When were the most famous parts built?', o: ['Two thousand years ago', 'About five hundred years ago', 'In the twentieth century', 'One hundred years ago'], a: 1, x: 'Dynastie Ming, ~500 ans.' }, { q: 'What was one purpose of the walls, other than defense?', o: ['To mark the border with Japan', 'To control trade and travel', 'To store food', 'To attract tourists'], a: 1, x: '« control trade and travel ».' }, { q: 'Why can\'t the wall be seen from space?', o: ['It is too short', 'It is too narrow', 'It is hidden by clouds', 'It has been destroyed'], a: 1, x: '« too narrow ».' }] },
  { id: 't09', diff: 2, g: 'W', ctx: 'Listen to part of a lecture in a linguistics class.', text: 'Let\'s look at how children acquire language. One striking observation is what we call overregularization. At some point, a child who correctly said "went" suddenly starts saying "goed." Parents sometimes worry that their child is getting worse. But linguists see it as a sign of progress. Why? Because the child has discovered a rule, add "-ed" for the past tense, and is now applying it everywhere, even where it doesn\'t belong. Earlier, "went" was simply memorized as a separate word. Eventually, the child learns the exceptions, and "went" comes back. This U-shaped pattern, correct, then incorrect, then correct again, shows that children aren\'t just imitating adults; after all, adults never say "goed."',
    qs: [{ q: 'What is overregularization?', o: ['Using a grammatical rule in cases where it does not apply', 'Speaking too slowly', 'Learning two languages', 'Repeating adults exactly'], a: 0, x: 'Appliquer une règle partout, même aux exceptions.' }, { q: 'Why do linguists view "goed" as progress?', o: ['It shows the child has learned a general rule', 'It is correct in some dialects', 'It is easier to pronounce', 'It shows better memory'], a: 0, x: 'L\'enfant a découvert la règle du -ed.' }, { q: 'What does the "U-shaped pattern" refer to?', o: ['Correct use, then errors, then correct use again', 'The shape of the mouth', 'Increasing vocabulary', 'A drawing test'], a: 0, x: 'Correct → incorrect → correct.' }, { q: 'Why does the professor say adults never say "goed"?', o: ['To show children are not simply imitating', 'To criticize parents', 'To explain regional accents', 'To show adults make fewer mistakes'], a: 0, x: 'Preuve qu\'ils ne font pas qu\'imiter.' }] },
  { id: 't10', diff: 3, g: 'M', ctx: 'Listen to part of a lecture in a finance class.', text: 'Let\'s discuss why stock prices sometimes seem to overreact. Consider a company that reports three consecutive quarters of strong earnings. Investors tend to extrapolate, assuming the trend will continue indefinitely, and they bid the price up well beyond what the fundamentals justify. Then, when growth inevitably slows, the correction can be brutal. Researchers Werner De Bondt and Richard Thaler found evidence consistent with this. Portfolios of stocks that had performed worst over the previous three to five years subsequently outperformed the prior winners. Now, this finding is controversial. Defenders of market efficiency argue that the "losers" were simply riskier, so their higher returns were compensation for that risk, not evidence of irrationality. Separating these two explanations empirically turns out to be remarkably difficult.',
    qs: [{ q: 'According to the professor, why might investors overreact to strong earnings?', o: ['They assume past trends will continue', 'They lack access to information', 'They are forced to buy by regulators', 'They expect prices to fall'], a: 0, x: 'Extrapolation de la tendance.' }, { q: 'What did De Bondt and Thaler find?', o: ['Past winners continued to outperform', 'Past losers later outperformed past winners', 'Prices always reflect fundamentals', 'Earnings do not affect prices'], a: 1, x: 'Les perdants ont ensuite surperformé.' }, { q: 'How do defenders of market efficiency interpret the finding?', o: ['As proof of irrationality', 'As compensation for higher risk', 'As a statistical error', 'As insider trading'], a: 1, x: 'Rendement plus élevé = prime de risque.' }, { q: 'What does the professor suggest in the last sentence?', o: ['The debate is easily resolved', 'It is hard to determine which explanation is correct', 'Efficiency has been disproved', 'Research should stop'], a: 1, x: '« remarkably difficult ».' }] },
  { id: 't11', diff: 2, g: 'W', ctx: 'Listen to part of a lecture in an astronomy class.', text: 'Why do we have seasons? A common answer is that the Earth is closer to the Sun in summer. That sounds logical, but it\'s wrong. In fact, the Earth is closest to the Sun in early January, which is winter in the Northern Hemisphere. The real reason is the tilt of the Earth\'s axis, about twenty-three and a half degrees. When the Northern Hemisphere is tilted toward the Sun, sunlight hits it more directly and days are longer, so it\'s summer there. At the same time, the Southern Hemisphere is tilted away, so it experiences winter. That\'s also why seasons are reversed between, say, France and Australia.',
    qs: [{ q: 'What misconception does the professor mention?', o: ['That the Earth has no tilt', 'That seasons are caused by distance from the Sun', 'That Australia has no seasons', 'That January is summer everywhere'], a: 1, x: 'La distance n\'est pas la cause.' }, { q: 'When is the Earth closest to the Sun?', o: ['In July', 'In early January', 'In spring', 'It never changes'], a: 1, x: '« early January ».' }, { q: 'What actually causes the seasons?', o: ['The Earth\'s tilted axis', 'Changes in the Sun\'s temperature', 'The Moon', 'Ocean currents'], a: 0, x: 'L\'inclinaison de l\'axe.' }, { q: 'Why does the professor mention France and Australia?', o: ['To illustrate that seasons are opposite in the two hemispheres', 'To compare their climates', 'To show where astronomy began', 'To discuss time zones'], a: 0, x: 'Saisons inversées.' }] },
  { id: 't12', diff: 3, g: 'M', ctx: 'Listen to part of a lecture in a sociology class.', text: 'Robert Putnam\'s book "Bowling Alone" argued that American social capital declined sharply in the late twentieth century. By social capital, Putnam meant the networks, norms, and trust that enable people to cooperate. His famous illustration was that more Americans were bowling than ever, but fewer were bowling in organized leagues. Why does that matter? Because leagues bring together people who might not otherwise interact, building trust that spills over into civic life. Putnam pointed to several causes, but he singled out television as a major one, since it privatized leisure time. Critics, however, argued that he overlooked new forms of association, such as advocacy groups and, later, online communities. Whether these newer forms generate the same kind of trust remains an open question.',
    qs: [{ q: 'What is social capital, according to Putnam?', o: ['Money invested in communities', 'Networks, norms, and trust that facilitate cooperation', 'The number of bowling alleys', 'Government funding for clubs'], a: 1, x: 'Définition donnée.' }, { q: 'Why does the professor mention bowling leagues?', o: ['To show that bowling became less popular', 'To illustrate a decline in organized group activities', 'To promote bowling', 'To explain television ratings'], a: 1, x: 'Plus de joueurs, moins de ligues.' }, { q: 'What cause did Putnam emphasize?', o: ['Television', 'Economic crisis', 'Immigration', 'Urban planning'], a: 0, x: 'La télévision a privatisé les loisirs.' }, { q: 'What did critics argue?', o: ['Putnam ignored newer kinds of groups', 'Bowling leagues were growing', 'Trust had increased', 'Television was harmless'], a: 0, x: '« overlooked new forms of association ».' }] },
  { id: 't13', diff: 1, g: 'W', ctx: 'Listen to part of a talk in a nutrition class.', text: 'Today I want to talk about breakfast. You\'ve probably heard that breakfast is the most important meal of the day. Is that true? Well, research gives mixed answers. Some studies found that people who eat breakfast are healthier. But these people also tend to exercise more and smoke less, so it\'s hard to know if breakfast itself is the reason. When scientists ran controlled experiments, skipping breakfast did not always lead to weight gain. What seems to matter more is the quality of what you eat during the whole day, not the exact time.',
    qs: [{ q: 'What question does the talk examine?', o: ['Whether breakfast is really the most important meal', 'How to cook breakfast', 'Why people skip lunch', 'How much people should exercise'], a: 0, x: 'Le petit-déjeuner est-il le repas le plus important ?' }, { q: 'Why is it hard to interpret the early studies?', o: ['Breakfast eaters also had other healthy habits', 'The studies were too small', 'People lied about breakfast', 'Scientists disagreed about food'], a: 0, x: 'Ils font aussi plus de sport, fument moins.' }, { q: 'What did controlled experiments show?', o: ['Skipping breakfast always causes weight gain', 'Skipping breakfast did not always cause weight gain', 'Breakfast should be large', 'People should eat five meals'], a: 1, x: '« did not always lead to weight gain ».' }, { q: 'What is the speaker\'s conclusion?', o: ['Everyone must eat breakfast', 'Overall diet quality matters more than meal timing', 'Breakfast is dangerous', 'Research is useless'], a: 1, x: 'La qualité de l\'alimentation sur la journée.' }] },
  { id: 't14', diff: 2, g: 'M', ctx: 'Listen to part of a lecture in a marketing class.', text: 'Let\'s talk about the decoy effect. Imagine a cinema selling popcorn in two sizes: small for three dollars and large for seven. Most people buy the small one. Now the cinema adds a medium size for six fifty. Suddenly, many more people buy the large. Why? Because next to the medium, the large looks like a bargain; for just fifty cents more, you get much more popcorn. The medium size isn\'t really meant to be bought. It\'s a decoy, designed to make the large option look better by comparison. This shows that our choices depend not only on the options themselves, but on how they compare to each other.',
    qs: [{ q: 'What happens when the medium size is introduced?', o: ['Most people buy the medium', 'More people buy the large', 'Sales of popcorn fall', 'The small becomes more popular'], a: 1, x: 'Plus de grands formats vendus.' }, { q: 'What is the purpose of the decoy?', o: ['To be the best-selling product', 'To make another option look more attractive', 'To reduce prices', 'To confuse employees'], a: 1, x: 'Faire paraître le grand format avantageux.' }, { q: 'Why does the large size look like a bargain?', o: ['It costs only slightly more than the medium', 'It is cheaper than the small', 'It is on sale', 'It includes a drink'], a: 0, x: '50 centimes de plus seulement.' }, { q: 'What general point does the professor make?', o: ['People always choose the cheapest option', 'Choices are influenced by comparisons between options', 'Popcorn is overpriced', 'Consumers are always rational'], a: 1, x: 'Les choix dépendent des comparaisons.' }] },
  { id: 't15', diff: 3, g: 'W', ctx: 'Listen to part of a lecture in an ecology class.', text: 'We often assume that removing an invasive species will automatically help native wildlife. But ecosystems are more tangled than that. Consider islands where cats were introduced and began preying on seabirds. On one sub-Antarctic island, conservationists eradicated the cats, expecting the birds to recover. Instead, the rabbit population, which the cats had kept in check, exploded. The rabbits stripped much of the island\'s vegetation, damaging the very habitat the seabirds depended on. Eventually, a costly second campaign was needed to remove the rabbits. The lesson isn\'t that eradication is a bad idea; it\'s that managers need to model the whole food web before intervening, because a predator may be suppressing another invasive species.',
    qs: [{ q: 'What assumption does the professor challenge?', o: ['That cats are harmless', 'That removing an invasive species always benefits native wildlife', 'That rabbits eat birds', 'That islands have simple ecosystems'], a: 1, x: 'Retirer une espèce invasive n\'aide pas forcément.' }, { q: 'What happened after the cats were removed?', o: ['The seabirds recovered immediately', 'The rabbit population increased dramatically', 'The vegetation grew back', 'The cats returned'], a: 1, x: '« the rabbit population... exploded ».' }, { q: 'How did the rabbits harm the seabirds?', o: ['By eating their eggs', 'By destroying vegetation the birds relied on', 'By spreading disease', 'By competing for fish'], a: 1, x: 'Destruction de l\'habitat.' }, { q: 'What is the professor\'s main lesson?', o: ['Eradication should never be attempted', 'The entire food web should be analyzed before intervening', 'Cats should be introduced to islands', 'Rabbits are the most dangerous species'], a: 1, x: '« model the whole food web before intervening ».' }] },
  { id: 't16', diff: 2, g: 'M', ctx: 'Listen to part of a lecture in a history of technology class.', text: 'When we think of the invention of the light bulb, we usually think of Thomas Edison. But Edison didn\'t invent the first electric light. Several inventors, including Joseph Swan in England, had produced working bulbs before him. Their problem was that the bulbs burned out very quickly. Edison\'s real achievement was making the light bulb practical and long-lasting, by testing thousands of materials for the filament. Even more important, he built an entire system around it: power stations, wiring, and meters to charge customers. In other words, Edison\'s genius was less about a single invention and more about creating the infrastructure that made electric lighting a business.',
    qs: [{ q: 'What misconception does the professor correct?', o: ['That Edison invented the first electric light', 'That Swan was American', 'That light bulbs use filaments', 'That Edison built power stations'], a: 0, x: 'D\'autres avaient fait des ampoules avant.' }, { q: 'What was the problem with earlier bulbs?', o: ['They were too bright', 'They did not last long', 'They were too expensive to buy', 'They used too much gas'], a: 1, x: '« burned out very quickly ».' }, { q: 'According to the professor, what was Edison\'s most important contribution?', o: ['Inventing the filament', 'Building a complete system for electric lighting', 'Working with Swan', 'Selling bulbs in England'], a: 1, x: 'L\'infrastructure complète.' }, { q: 'Why does the professor mention meters?', o: ['As part of the system that turned lighting into a business', 'To criticize high prices', 'To explain how bulbs work', 'To describe Swan\'s invention'], a: 0, x: 'Pour facturer les clients : modèle économique.' }] },
  { id: 't17', diff: 3, g: 'W', ctx: 'Listen to part of a lecture in a political science class.', text: 'Let\'s examine the paradox of voting, first formalized by Anthony Downs. From a strictly rational perspective, voting seems puzzling. The probability that your single vote will decide an election is astronomically small, while voting has real costs: time, travel, gathering information. So a purely self-interested calculation would suggest staying home. Yet millions of people vote. How do we explain this? One response is that people derive intrinsic satisfaction from voting, a sense of civic duty. Critics object that this rescues the theory by simply adding whatever preference is needed, which makes it unfalsifiable. Another approach suggests people think of voting as part of a group, reasoning that if people like them vote, their side can win. The debate is useful precisely because it exposes the limits of narrow rational-choice models.',
    qs: [{ q: 'What is the "paradox of voting"?', o: ['People vote even though a single vote is extremely unlikely to change the result', 'Elections are always close', 'Rational people never vote', 'Voting is free'], a: 0, x: 'Coûts réels, influence quasi nulle, et pourtant on vote.' }, { q: 'What criticism is made of the "civic duty" explanation?', o: ['It is too expensive', 'It makes the theory impossible to test', 'It ignores group behavior', 'It is supported by no one'], a: 1, x: '« unfalsifiable ».' }, { q: 'What does the group-based approach suggest?', o: ['People vote to meet friends', 'People think about the combined effect of similar voters', 'Groups force people to vote', 'People vote randomly'], a: 1, x: 'Raisonner comme membre d\'un groupe.' }, { q: 'Why does the professor consider the debate useful?', o: ['It proves people are irrational', 'It reveals weaknesses of narrow rational-choice models', 'It predicts election results', 'It ends the discussion'], a: 1, x: '« exposes the limits of narrow rational-choice models ».' }] },
  { id: 't18', diff: 1, g: 'M', ctx: 'Listen to part of a talk in an introduction to business class.', text: 'Let\'s talk about why some small businesses fail. Many people think the main reason is a bad product. Sometimes that\'s true. But very often, the problem is cash flow. A business can be profitable on paper and still run out of money. How? Imagine a company sells a lot of products, but its customers pay sixty days later. Meanwhile, the company must pay rent, salaries, and suppliers every month. If it doesn\'t have enough cash to cover those costs, it can go bankrupt, even with many sales. That\'s why managers watch cash flow as carefully as profit.',
    qs: [{ q: 'What does the speaker say is a common cause of small-business failure?', o: ['Too many customers', 'Cash-flow problems', 'High product quality', 'Low rent'], a: 1, x: 'La trésorerie.' }, { q: 'How can a profitable company run out of money?', o: ['Its customers pay late while its costs must be paid now', 'It sells too few products', 'It has no suppliers', 'It pays no salaries'], a: 0, x: 'Clients à 60 jours, charges mensuelles.' }, { q: 'Which costs are mentioned?', o: ['Rent, salaries, and suppliers', 'Advertising and taxes', 'Travel and training', 'Insurance and loans'], a: 0, x: 'Loyer, salaires, fournisseurs.' }, { q: 'What is the speaker\'s main advice for managers?', o: ['Focus only on profit', 'Monitor cash flow as closely as profit', 'Sell more products', 'Avoid customers who pay late'], a: 1, x: '« watch cash flow as carefully as profit ».' }] },
];
